test("AC-1 Each product in the list shows a picture and no two products show the same picture", async ({ page }) => {
  const productListPage = new ProductListPage(page);

  await test.step("Given I am on the sign-in page", async () => {
    await productListPage.goto();
  });

  await test.step("When I sign in as standard_user", async () => {
    await productListPage.usernameInput.fill(process.env["AQA_APP_USER"] ?? "standard_user");
    await productListPage.passwordInput.fill(process.env["AQA_APP_PASS"] ?? "secret_sauce");
    await productListPage.loginButton.click();
  });

  await test.step("Then the product list is shown", async () => {
    await expect(page.getByText("Products").first()).toBeVisible();
  });

  await test.step("Precondition: product images are present in the list", async () => {
    await expect(page.locator("[data-test='inventory-item-img']").first()).toBeVisible({ timeout: 10000 });
  });

  await test.step("Then each product card image is visible", async () => {
    const images = page.locator("[data-test='inventory-item-img']");
    const count = await images.count();
    expect(count, "Expected at least one product image").toBeGreaterThan(0);
    for (let i = 0; i < count; i++) {
      await expect(images.nth(i)).toBeVisible();
    }
  });

  await test.step("And no two product images show the same picture", async () => {
    const images = page.locator("[data-test='inventory-item-img']");
    const count = await images.count();
    const srcs: string[] = [];
    for (let i = 0; i < count; i++) {
      const src = await images.nth(i).getAttribute("src");
      expect(src, `Image ${i} has no src`).toBeTruthy();
      srcs.push(src!);
    }
    const uniqueSrcs = new Set(srcs);
    expect(uniqueSrcs.size, `Expected all ${count} product images to have unique src values, but found ${uniqueSrcs.size} unique srcs`).toBe(count);
  });
});

